python3 << 'EOF'
import json

with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Search for AY-1 table data
def find_ay1_table(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            results.extend(find_ay1_table(v, f"{path}.{k}"))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_ay1_table(v, f"{path}[{i}]"))
    elif isinstance(obj, str) and 'AY-1' in obj:
        results.append((path, obj[:200]))
    return results

results = find_ay1_table(data)
print(f"Found {len(results)} AY-1 references")
for path, text in results[:5]:
    print(f"  {path}: {text}")
EOF
